<hr class="sidhuvud_linje"/>


		<div class="Section1">
			<p class="Normalutanindragellerluft">
				<a name="_Toc106800475"></a><a name="_Toc106801300"><span style="-aw-import:ignore">&#xa0;</span></a>
			</p>
			<p class="RubrikFrslagTIllRiksdagsbeslut">
				<span style="-aw-sdt-tag:'CC_Boilerplate_4'; -aw-sdt-title:'CC_Boilerplate_4'"><span>Förslag till riksdagsbeslut</span></span><span style="-aw-bookmark-end:_Toc106800475"></span><span style="-aw-bookmark-end:_Toc106801300"></span>
			</p>
			<div style="-aw-sdt-tag:'f5ccab9a-3697-40c8-bc19-dbb15620581f'; -aw-sdt-title:'Yrkande 1'">
				<ol type="1" style="margin:0pt; padding-left:0pt">
					<li class="Frslagstext" style="margin-left:14pt; t-i:0pt; padding-left:5.85pt">
						<span>Riksdagen avslår förslagen till ändringar i 1 kap. 6 § brottsbalken avseende sänkt straffbarhetsålder och eventuella följdändringar.</span>
					</li>
				</ol>
			</div>
			<div style="-aw-sdt-tag:'11eeebe9-ffbe-4932-88d6-34ea840a9381'; -aw-sdt-title:'Yrkande 2'">
				<ol start="2" type="1" style="margin:0pt; padding-left:0pt">
					<li class="Frslagstext" style="margin-top:0pt; margin-left:14pt; t-i:0pt; padding-left:5.85pt">
						<span>Riksdagen avslår förslagen till ändringar i 29 kap. 7 § andra stycket brottsbalken avseende straffmaximum för barn under 18 år och eventuella följdändringar.</span>
					</li>
				</ol>
			</div>
			<div style="-aw-sdt-tag:'b6ec8609-4c28-411e-97ad-439fc22aa629'; -aw-sdt-title:'Yrkande 3'">
				<ol start="3" type="1" style="margin:0pt; padding-left:0pt">
					<li class="Frslagstext" style="margin-top:0pt; margin-left:14pt; t-i:0pt; padding-left:5.85pt">
						<span>Riksdagen avslår förslagen till ändringar i 32 kap. brottsbalken avseende ungdomsvård och eventuella följdändringar.</span>
					</li>
				</ol>
